    """Apply legacy NVL numeric behavior, avoiding binary-float rounding artifacts."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, str):
        if value.strip() == "":
            return Decimal("0")
        return Decimal(value)
    if isinstance(value, float):
        return Decimal(str(value))
    return Decimal(value)


