    # Blank DEL_FLG follows the legacy CHAR(1) boolean convention and means N.
    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total = Decimal("0")

    with localcontext() as context:
        context.prec = 100

